public static class Validate {
    static void Need(bool test,string message){if(!test)throw new Exception(message);}
    static object CodecChecks(){var random=new Random(907);int checks=0;foreach(var size in new[]{new Size(2,2),new Size(64,64),new Size(65,67),new Size(127,129),new Size(960,541)}){
        byte[] prior=new byte[size.Width*size.Height*3];random.NextBytes(prior);byte[] current=(byte[])prior.Clone();int[] points={0,prior.Length-1,Math.Min(prior.Length-1,64*3),prior.Length/2};foreach(int at in points)current[at]^=0x9b;
        int[] tiles=Wire.ChangedTiles(current,prior,size.Width,size.Height,64);byte[] packed=Wire.PackTiles(current,prior,tiles,size.Width,size.Height,64);byte[] restored=(byte[])prior.Clone();byte[] encoded=Wire.Deflate(packed);Wire.ApplyTiles(restored,Wire.Inflate(encoded,packed.Length),tiles,size.Width,size.Height,64);Need(Wire.Equal(restored,current),"Tile edge restoration failed");Need(Wire.ChangedTiles(prior,prior,size.Width,size.Height,64).Length==0,"Unchanged tile detection failed");checks+=2;
    }
        byte[] raw=new byte[1024*640*3];random.NextBytes(raw);string hash=Wire.Hash(raw);var decoder=new FrameDecoder();using(var preview=decoder.Decode(new Packet{Header=Wire.Map("encoding","bgr_deflate","width",1024,"height",640,"window",1L,"sequence",1L,"raw_sha256",hash),Data=Wire.Deflate(raw)},320)){Need(preview.Width==320&&preview.Height==200,"Preview aspect ratio failed");var native=decoder.NativeSnapshot();Need(Wire.Int(native,"width")==1024&&Wire.Int(native,"height")==640&&Wire.Equal((byte[])native["bgr24"],raw),"Native pixels altered by preview");((byte[])native["bgr24"])[0]^=1;Need(Wire.Hash((byte[])decoder.NativeSnapshot()["bgr24"])==hash,"Native snapshot was mutable");checks+=3;}return Wire.Map("checks",checks,"edge_tiles",true,"preview_320x200_native_1024x640",true,"independent_snapshot",true);
    }
    static Dictionary<string,object> Mouse(string op,long window,int x,int y){return Wire.Map("op",op,"window",window,"x",x,"y",y,"width",480,"height",340,"button",1);}
    public static void Main(string[] args){string root=args[0];var report=Wire.Map("game_input",false);Session session=null;Link frame=null,control=null;try{
        report["codec"]=CodecChecks();session=new Session(root);session.Start(true,true);report["ready"]=session.Ready;var test=(Dictionary<string,object>)session.Ready["test"];long window=Wire.Long(test,"window");frame=new Link(session.Port,session.Token,"frame");control=new Link(session.Port,session.Token,"control");var decoder=new FrameDecoder();var samples=new List<object>();
        var vision=control.Call(Wire.Map("op","prepare_vision","window",window)).Header;var preparedFrame=frame.Call(Wire.Map("op","frame","window",window));using(var image=decoder.Decode(preparedFrame)){}var readOnlyState=control.Call(Wire.Map("op","status")).Header;Need(!Wire.Bool(readOnlyState,"armed")&&Wire.Int(readOnlyState,"held")==0,"Vision preparation armed input");Need(!Wire.Bool(preparedFrame.Header,"cursor_in_game"),"Vision preparation left cursor inside target");DateTime preparedAt=DateTime.Parse(Wire.Str(vision,"prepared_utc"),null,System.Globalization.DateTimeStyles.RoundtripKind);DateTime capturedAt=DateTime.Parse(Wire.Str(preparedFrame.Header,"captured_utc"),null,System.Globalization.DateTimeStyles.RoundtripKind);Need(capturedAt>=preparedAt,"Vision used pre-prepare frame");report["vision_prepare_read_only"]=true;report["vision_prepare_fresh_frame"]=true;
        for(int i=0;i<12;i++){control.Call(Wire.Map("op","ping"));var packet=frame.Call(Wire.Map("op","frame","window",window));using(var image=decoder.Decode(packet)){Need(image.Width==480&&image.Height==340,"Frame size");if(i==0)image.Save(Path.Combine(root,"test-frame.png"));}samples.Add(Wire.Map("encoding",Wire.Str(packet.Header,"encoding"),"bytes",packet.Data.Length,"processing_ms",packet.Header["processing_ms"]));Thread.Sleep(25);}report["lossless_pixel_hashes"]=12;report["samples"]=samples;
        bool rejected=false;try{new FrameDecoder().Decode(new Packet{Header=Wire.Map("encoding","xor_deflate","width",2,"height",2,"base_sequence",1),Data=Wire.Deflate(new byte[12])});}catch(InvalidDataException){rejected=true;}Need(rejected,"Stale delta accepted");report["stale_delta_rejected"]=true;
        control.Call(Wire.Map("op","arm","window",window));var coords=new List<object>();foreach(var point in new[]{new Point(21,76),new Point(22,76),new Point(23,77),new Point(90,95)}){var result=control.Call(Mouse("mouse_move",window,point.X,point.Y)).Header;Need(Wire.Int(result,"client_x")==point.X&&Wire.Int(result,"client_y")==point.Y,"Mouse pixel mismatch");coords.Add(Wire.Map("x",point.X,"y",point.Y,"actual_x",Wire.Int(result,"client_x"),"actual_y",Wire.Int(result,"client_y")));}report["pixel_mouse_positions"]=coords;
        // Rendering a window classified as a game must never move its cursor.
        Need(Wire.Bool(control.Call(Wire.Map("op","status")).Header,"armed"),"Bridge mouse movement was misclassified as local input");
        var expectedCursor=control.Call(Wire.Map("op","status")).Header;control.Call(Wire.Map("op","release"));
        for(int i=0;i<20;i++){control.Call(Wire.Map("op","ping"));using(var image=decoder.Decode(frame.Call(Wire.Map("op","frame","window",window)))){}Thread.Sleep(25);}
        var afterCapture=control.Call(Wire.Map("op","status")).Header;Need(Wire.Int(afterCapture,"cursor_x")==Wire.Int(expectedCursor,"cursor_x")&&Wire.Int(afterCapture,"cursor_y")==Wire.Int(expectedCursor,"cursor_y")&&Wire.Long(afterCapture,"remote_moves")==Wire.Long(expectedCursor,"remote_moves"),"Preview moved the computer1 cursor");report["capture_does_not_move_mouse"]=true;
        control.Call(Wire.Map("op","arm","window",window));
        control.Call(Mouse("mouse_down",window,90,95));control.Call(Mouse("mouse_up",window,90,95));control.Call(Mouse("mouse_down",window,100,158));control.Call(Mouse("mouse_up",window,100,158));
        control.Call(Wire.Map("op","text","text","SSH_OK 测试"));control.Call(Wire.Map("op","key_down","vk",0x26));control.Call(Wire.Map("op","key_down","vk",0x27));Thread.Sleep(130);control.Call(Wire.Map("op","key_up","vk",0x27));control.Call(Wire.Map("op","key_up","vk",0x26));control.Call(Wire.Map("op","release"));report["mouse_keyboard_sent"]=true;
        control.Call(Wire.Map("op","arm","window",window));control.Call(Wire.Map("op","record_keys","enabled",true,"window",window,"keys",new[]{37,38,39,40,17}));
        control.Call(Wire.Map("op","key_down","vk",38));control.Call(Wire.Map("op","key_down","vk",39));control.Call(Wire.Map("op","key_down","vk",17));control.Call(Wire.Map("op","key_up","vk",17));Thread.Sleep(50);
        var routeFrame=frame.Call(Wire.Map("op","frame","window",window));var routeInput=routeFrame.Header["route_input"] as Dictionary<string,object>;Need(routeInput!=null&&Wire.Bool(routeInput,"foreground"),"Route key observation not active");var heldKeys=Wire.IntArray(routeInput["down"]);Need(heldKeys.Contains(38)&&heldKeys.Contains(39)&&!heldKeys.Contains(17),"Route key snapshot lost combination");bool press=false,release=false;foreach(object entry in (System.Collections.IEnumerable)routeInput["events"]){var item=entry as Dictionary<string,object>;if(Wire.Int(item,"vk")==17){if(Wire.Bool(item,"down"))press=true;else release=true;}}Need(press&&release,"Short route key tap lost between frames");report["route_key_observation"]=Wire.Map("target_scoped",true,"combined_up_right",true,"frame_interval_short_tap",true,"events",routeInput["events"]);
        control.Call(Wire.Map("op","key_up","vk",38));control.Call(Wire.Map("op","key_up","vk",39));control.Call(Wire.Map("op","release"));control.Call(Wire.Map("op","record_keys","enabled",false));Need(frame.Call(Wire.Map("op","frame","window",window)).Header["route_input"]==null,"Route observer stayed enabled");report["route_observer_disabled"]=true;
        control.Call(Wire.Map("op","arm","window",window));control.Call(Wire.Map("op","key_down","vk",0x25));control.Dispose();control=null;Thread.Sleep(250);control=new Link(session.Port,session.Token,"control");var status=control.Call(Wire.Map("op","status")).Header;Need(Wire.Int(status,"held")==0&&!Wire.Bool(status,"armed"),"Disconnect release failed");report["disconnect_released"]=true;
        control.Call(Wire.Map("op","arm","window",window));control.Call(Wire.Map("op","key_down","vk",0x27));Thread.Sleep(1450);status=control.Call(Wire.Map("op","status")).Header;Need(Wire.Int(status,"held")==0&&!Wire.Bool(status,"armed"),"Watchdog failed");report["watchdog_released"]=true;
        control.Call(Wire.Map("op","arm","window",window));rejected=false;try{control.Call(Mouse("mouse_down",0,40,40));}catch(IOException){rejected=true;}Need(rejected,"Wrong target accepted");Need(!Wire.Bool(control.Call(Wire.Map("op","status")).Header,"armed"),"Wrong target retained lease");report["wrong_window_rejected"]=true;
        control.Call(Wire.Map("op","arm","window",window));control.Call(Wire.Map("op","key_down","vk",0x25));var beforeLocal=control.Call(Wire.Map("op","status")).Header;control.Call(Wire.Map("op","test_local_mouse"));Thread.Sleep(300);var local=control.Call(Wire.Map("op","status")).Header;report["local_before"]=beforeLocal;report["local_after"]=local;Need(!Wire.Bool(local,"armed")&&Wire.Int(local,"held")==0&&Wire.Long(local,"local_generation")>Wire.Long(beforeLocal,"local_generation"),"Computer1 local mouse did not take over");report["local_mouse_takeover"]=true;report["local_takeover_reason"]=Wire.Str(local,"reason");
        report["ok"]=true;
    }catch(Exception e){report["ok"]=false;report["error"]=e.Message;Environment.ExitCode=1;}finally{if(control!=null){try{control.Call(Wire.Map("op","release"));}catch{}control.Dispose();}if(frame!=null)frame.Dispose();if(session!=null){session.Dispose();report["cleanup"]=session.Cleanup;if(session.Cleanup!=null){object proof;if(session.Cleanup.TryGetValue("testProof",out proof)){var p=proof as Dictionary<string,object>;bool passed=p!=null&&Wire.Int(p,"clicks")>=1&&Wire.Str(p,"text")=="SSH_OK 测试"&&Wire.Bool(p,"combo")&&!Wire.Bool(p,"left_down")&&!Wire.Bool(p,"up_down")&&!Wire.Bool(p,"right_down");report["test_window_proof_passed"]=passed;if(!passed){report["ok"]=false;Environment.ExitCode=1;}}}else{report["ok"]=false;if(!report.ContainsKey("error"))report["error"]="Cleanup receipt missing";Environment.ExitCode=1;}}Wire.Save(Path.Combine(root,"validation.json"),report);Console.WriteLine(new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(report));}}
}
